// Presentation-only schedule and retained typed-buffer inventory. No DOM or room globals.
function makeFidelityFramework(){
  const phases=Object.create(null),resources=[],names=new Set(),buffers=new Map();let sealed=false,bytes=0;
  return {
    stage(phase,id,callback){
      if(sealed)throw Error('Framework sealed');
      if(!phase||!id||typeof callback!=='function')throw Error('Invalid stage callback');
      const key=phase+'.'+id;if(names.has(key))throw Error('duplicate stage '+key);
      names.add(key);(phases[phase]||(phases[phase]=[])).push({id,callback});
    },
    own(owner,id,array){
      if(sealed)throw Error('Resource inventory sealed');
      const key=owner+'.'+id;if(names.has(key))throw Error('duplicate resource '+key);
      if(!ArrayBuffer.isView(array)||!Number.isInteger(array.BYTES_PER_ELEMENT))throw Error('Expected typed array '+key);
      names.add(key);const aliasOf=buffers.get(array.buffer)||null,size=aliasOf?0:array.buffer.byteLength;
      if(!aliasOf)buffers.set(array.buffer,key);bytes+=size;
      resources.push({id:key,array,bytes:size,aliasOf});
    },
    seal(){sealed=true;},
    run(phase){
      if(!sealed)throw Error('seal schedule before running');
      const list=phases[phase];if(!list)throw Error('Unknown phase '+phase);
      for(let n=0;n<list.length;n++)list[n].callback();
    },
    // Diagnostics only: returns new metadata, never called by a drawing stage.
    report(){return {sealed,bytes,buffers:buffers.size,resources:resources.map(r=>({id:r.id,bytes:r.bytes,aliasOf:r.aliasOf})),
      phases:Object.fromEntries(Object.entries(phases).map(([name,list])=>[name,list.map(s=>s.id)]))};}
  };
}

